package cn.zhuatech.maintenanceai.controller; import cn.zhuatech.maintenanceai.common.ApiResponse; import cn.zhuatech.maintenanceai.dto.MaintenanceAiDto.*; import cn.zhuatech.maintenanceai.service.MaintenanceAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final MaintenanceAiService service;public OperationsAdminController(MaintenanceAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
